  "items:ring_master_attack:description": "Gagné par une lame qui a trouvé chaque faille dans chaque garde. Confère 2 % de pénétration d'armure.",
  "items:ring_master_attack:name": "Anneau du Maître d'Armes",
  "items:ring_master_completion:description": "Porté uniquement par ceux qui ont maîtrisé les vingt et une disciplines. Un discret anneau d'or, accordé, jamais acheté.",
  "items:ring_master_hunting:name": "Anneau du Trappeur",
  "items:ring_master_hunting:description": "Lissé par mille pièges posés et déclenchés. Chaque butin d'une capture a 5 % de chance de tomber en double.",
  "items:ring_master_completion:name": "Anneau de l'Accomplissement",
  "items:ring_master_cooking:description": "Taché par chaque plat qu'il a supervisé. Les plats préparés en le portant ne ratent jamais.",
  "items:ring_master_cooking:name": "Anneau de l'Âme-Cuisinier",
  "items:ring_master_defence:description": "A dévié des coups qui auraient terrassé des gardes moindres. Confère 2 % de chance de blocage.",
  "items:ring_master_defence:name": "Anneau du Bastion",
  "items:ring_master_farming:description": "Sent la terre retournée et les saisons patientes. Les parcelles mûrissent 8 % plus vite en le portant.",
  "items:ring_master_farming:name": "Anneau du Gardien des Tombes",
  "items:ring_master_fishing:description": "Sent vaguement l'eau profonde et des choses plus anciennes. 5 % de chance de faire une prise double.",
  "items:ring_master_fishing:name": "Anneau du Pêcheur du Vide",
  "items:ring_master_foraging:description": "Serti d'un éclat de chaque feuille qu'il a effleurée. 5 % de chance de récolter une double récolte.",
  "items:ring_master_foraging:name": "Anneau du Cueilleur Sauvage",
  "items:ring_master_herblore:description": "Infusé dans des vapeurs amères depuis plus longtemps que mémoire. Les toniques et breuvages durent 10 % plus longtemps en le portant.",
  "items:ring_master_herblore:name": "Anneau du Brasseur de Venin",
  "items:ring_master_jewelcrafting:description": "Capte la lumière comme mille gemmes non serties. 5 % de chance de tailler une gemme double.",
  "items:ring_master_jewelcrafting:name": "Anneau du Maître Lapidaire",
  "items:ring_master_leatherworking:description": "Sculpté par un maître qui ne gaspillait rien. 5 % de chance que l'artisanat épargne ses matériaux.",
  "items:ring_master_leatherworking:name": "Anneau du Maître Tanneur",
  "items:ring_master_magic:description": "Forgé à partir des résidus de mille protections brisées. Confère 3 % de rupture de protection.",
  "items:ring_master_magic:name": "Anneau de l'Archimage",
  "items:ring_master_mining:description": "Forgé dans les veines les plus profondes, il se souvient de chacune qu'il a touchée. 5 % de chance d'extraire un minerai double.",
  "items:ring_master_mining:name": "Anneau du Briseur des Profondeurs",
  "items:ring_master_power:description": "Porte le poids de chaque coup de grâce d'un seigneur de guerre. Confère 3 % de dégâts critiques.",
  "items:ring_master_power:name": "Anneau du Seigneur de Guerre",
  "items:ring_master_ranged:description": "Aiguise le regard jusqu'à ce qu'aucune esquive ne semble assez rapide. Confère 2 % de précision.",
  "items:ring_master_ranged:name": "Anneau de l'Œil de Faucon",
  "items:ring_master_runecrafting:description": "Bourdonne faiblement d'une écriture arcanique liée. 5 % de chance de lier une rune double.",
  "items:ring_master_runecrafting:name": "Anneau du Lieur de Runes",
  "items:ring_master_slayer:description": "Marqué du décompte de mille contrats. Rapporte 10 % de points de Traqueur en plus.",
  "items:ring_master_slayer:name": "Anneau du Maître des Primes",
  "items:ring_master_smithing:description": "Roussi par mille forges, jamais fondu. 5 % de chance que la forge épargne ses matériaux.",
