  "items:skytalon_recurve:name": "Arc recourbé serre-du-ciel",
  "items:slag_carapace:description": "Une chitine durcie et fondue à la lave, issue d'une abomination de scories. Matériau de qualité forge pour les pièces d'armure de la tour.",
  "items:slag_carapace:name": "Carapace de scories",
  "items:slagcarapace_plate:name": "Plastron en carapace de scories",
  "items:slagforged_sword:name": "Épée forgée de scories",
  "items:slagheart_cuirass:name": "Cuirasse cœur-de-scories",
  "items:slagweave_cape:name": "Cape tissée de scories",
  "items:slayer_amulet:description": "Une amulette cristalline sertie d'un éclat de héraut du néant. Elle émane une puissance froide et précise dans tous les styles de combat.",
  "items:slayer_amulet:name": "Amulette du Chasseur",
  "items:slayer_combat_draught:description": "Distillée à partir de l'essence de la Tour du Chasseur. Accélère vos frappes (-450ms d'intervalle d'attaque) et affine votre visée (+8% de critique) pendant 10 minutes.",
  "items:slayer_combat_draught:name": "Décoction de combat du Chasseur",
  "items:slayer_greaves:description": "Des grèves renforcées d'éclats brisés de dents de croc-d'effroi. Conçues pour une proie au-dessus de ton rang : +20 % de dégâts contre les monstres dont le niveau de combat est supérieur au tien.",
  "items:slayer_greaves:name": "Grèves du Chasseur",
  "items:slayer_helm:description": "Un heaume magistral forgé à partir de l'essence des pires horreurs de la Tour du Chasseur. Il marque la mission de son porteur : +20 % de dégâts contre la cible actuelle de la tâche, et aucun objet de barrière n'est nécessaire contre les menaces de la tour tant qu'il est porté.",
  "items:slayer_helm:name": "Heaume du Chasseur",
  "items:slayer_hunters_cape:description": "Une cape usée que Brenna remet aux chasseurs ayant gagné leurs trente premiers contrats. Le premier coup de chaque chasse porte le plus fort : +15 % de dégâts contre une cible indemne.",
  "items:slayer_hunters_cape:name": "Cape du Chasseur",
  "items:slayer_hunters_elixir:description": "Réservé aux Chasseurs vétérans. Accélère vos attaques (-600ms d'intervalle), +12% de critique, +20% de dégâts critiques pendant 30 minutes. Durée soutenue supérieure à la Décoction de combat.",
  "items:slayer_hunters_elixir:name": "Élixir de traque du Chasseur",
  "items:slayer_vambraces:description": "Des brassards façonnés dans une peau de Misérable des braises calcinée et du cuir de tour durci. Chaque élimination pendant la chasse referme les blessures du chasseur : +4 points de vie par élimination.",
  "items:slayer_vambraces:name": "Brassards du Chasseur",
  "items:slayer_war_brew:description": "Une formule ancestrale de Maître Chasseur. Accélère grandement vos attaques (-750ms d'intervalle), +20% de critique, +30% de dégâts critiques pendant 60 minutes. Réservée aux plus grandes traques.",
  "items:slayer_war_brew:name": "Breuvage de guerre du Chasseur",
  "items:slayer_ward_capsule:description": "Un réceptacle scellé contenant les quatre composants de barrière de la tour, fondus en un unique noyau protecteur.",
  "items:slayer_ward_capsule:name": "Capsule de barrière du Chasseur",
  "items:smokeweave_cape:name": "Cape tissée de fumée",
  "items:smugglers_key:name": "Clé du contrebandier",
  "items:sootscale_greaves:name": "Grèves en écailles de suie",
  "items:sorrow_staff:name": "Bâton du chagrin",
  "items:soul_amulet:name": "Amulette d'âme",
  "items:soul_flayer_fang:description": "Un croc recourbé empestant les âmes brûlées. Butin rare de l'écorcheur d'âmes, prisé comme trophée pour le Mur aux trophées du camp.",
  "items:cinderwretch_hide:name": "Peau du Misérable des braises",
  "items:cinderwretch_hide:description": "Une peau robuste, noircie par un cœur de braises éternel, arrachée à un Misérable des braises au plus profond de la tour. Composant de fabrication des Brassards du Chasseur.",
  "items:soul_flayer_fang:name": "Croc de l'écorcheur d'âmes",
  "items:soul_veil:description": "Un suaire chatoyant tissé d'essence d'aether et de runes du néant. Il repousse les attaques des créatures incorporelles.",
  "items:soul_veil:name": "Voile d'âme",
