  "quests:q_boar_hunter:description": "Tuez 15 sangliers sauvages dans les Pâturages. Sans clôture ni berger, ils ont pris leurs propres habitudes, et le Bastion des Braises a besoin de leur peau.",
  "quests:q_boar_hunter:name": "La Chasse sauvage",
  "quests:q_crypt_1:description": "Pénétrez dans la Crypte et tuez 10 guerriers squelettes. L'Ordre des Gardiens des Tombes les a scellés jadis ; le sceau ne tient plus partout.",
  "quests:q_crypt_1:name": "Ossements des défunts",
  "quests:q_crypt_2:description": "Les salles basses de la Crypte sont gardées par des lanciers squelettes, une garnison qui ne demande plus de solde. Abattez-en 20.",
  "quests:q_crypt_2:name": "Les Morts inflexibles",
  "quests:q_crypt_3:description": "Des mages de glace squelettes hantent les caveaux les plus profonds de la Crypte. Détruisez-en 10 avant qu'ils ne vous congèlent.",
  "quests:q_crypt_3:name": "Silence glacé",
  "quests:q_dire_wolf_hunt:description": "Des loups terribles traquent les profondeurs de Bois-Sauvage, plus grands qu'un loup ne devrait l'être. Tuez 15 de ces féroces prédateurs.",
  "quests:q_dire_wolf_hunt:name": "Terreur des étendues sauvages",
  "quests:q_fighter_1:description": "Vainquez 75 ennemis au total. Le sang et la sueur forgent le combattant dont le Bastion des Braises a besoin.",
