  "quests:q_fighter_2:description": "Abattez 200 ennemis au total. Les Serviteurs commencent déjà à retenir votre nom.",
  "quests:q_fighter_2:name": "Guerrier endurci",
  "quests:q_fighter_3:description": "Vainquez 500 ennemis au total. Chaque ennemi tombé est une entrée que la cendre ne garde jamais.",
  "quests:q_fighter_3:name": "Vétéran de cent batailles",
  "quests:q_first_blood:description": "Tuez 10 gobelins dans les Marches ; ils pillent les dernières fermes près du Bastion des Braises depuis trop longtemps.",
  "quests:q_first_blood:name": "Sang gobelin",
  "quests:q_first_steps:description": "Chassez 5 poulets dans les Pâturages, aux portes du Bastion des Braises : une première prise en main d'une arme, rien de plus.",
  "quests:q_first_steps:name": "Premiers pas",
  "quests:q_frost_hound:description": "Des molosses de givre rôdent dans les Cavernes de Givre, là où la fosse a creusé trop profond et trouvé le froid du vide. Chassez-en 15.",
  "quests:q_frost_hound:name": "La Chasse glaciale",
  "quests:q_gatherer:description": "Ramassez 50 objets de tout type pour le Bastion des Braises : coupez du bois, minez du minerai, cueillez des herbes ou pillez des monstres.",
  "quests:q_gatherer:name": "Cueilleur",
  "quests:q_gatherer_2:description": "Récoltez 5 000 objets au total pour le Bastion des Braises. Cette terre ne livre le peu qu'il lui reste qu'à ceux qui persévèrent.",
  "quests:q_gatherer_2:name": "Collectionneur acharné",
  "quests:q_goblin_slayer:description": "Repoussez encore la horde gobeline : tuez 30 gobelins dans les Marches, jadis le rempart-bouclier du Domaine.",
  "quests:q_goblin_slayer:name": "Pourfendeur de gobelins",
  "quests:q_miner_1:description": "Atteignez le niveau 5 en Minage et ouvrez de meilleurs filons pour la forge du Bastion des Braises.",
  "quests:q_miner_1:name": "La pioche et la pierre",
  "quests:q_miner_2:description": "Atteignez le niveau 30 en Minage. Les filons plus profonds des Marches exigent un bras plus vigoureux.",
  "quests:q_miner_2:name": "Volonté de fer",
  "quests:q_miner_3:description": "Atteignez le niveau 50 en Minage. Les minerais les plus rares du Domaine gisent loin sous la surface, plus profond que jamais.",
  "quests:q_miner_3:name": "L'Appel des profondeurs",
  "quests:q_moss_golem_hunt:description": "Les golems de mousse ont envahi les clairières de la forêt ; même le bois a besoin de gardes désormais. Fracassez-en 15.",
  "quests:q_moss_golem_hunt:name": "Menace moussue",
  "quests:q_roc_fledgling:description": "Les jeunes rocs règnent sur les courants ascendants des hautes terres, où le ciel reste encore pur. Abattez 10 de ces oiseaux colossaux.",
  "quests:q_roc_fledgling:name": "Guet du ciel des hautes terres",
  "quests:q_shaman_hunt:description": "Les chamans gobelins puisent l'Essence Trouble dans les vieux feux de garde et poussent la horde à la guerre. Faites-en taire 10.",
  "quests:q_shaman_hunt:name": "Chasse aux chamans",
  "quests:q_skiller_1:description": "Atteignez un niveau total cumulé de 20 sur l'ensemble des compétences ; le Bastion des Braises compte double chaque main capable.",
  "quests:q_skiller_1:name": "Touche-à-tout",
  "quests:q_skiller_2:description": "Atteignez un niveau total cumulé de 50. Qui ne maîtrise qu'un seul métier ne tient pas longtemps dans ce monde.",
  "quests:q_skiller_2:name": "Aventurier polyvalent",
  "quests:q_skiller_3:description": "Atteignez un niveau total cumulé de 75. Bien des chemins vous ont mené ici, et le Bastion des Braises n'en oublie aucun.",
  "quests:q_skiller_3:name": "Aventurier aguerri",
  "quests:q_skiller_4:description": "Atteignez un niveau total cumulé de 100. Peu de ceux partis du Bastion des Braises sont allés aussi loin.",
  "quests:q_skiller_4:name": "La Voie de la maîtrise",
  "quests:q_skiller_5:description": "Atteignez un niveau total cumulé de 150. Vos exploits se racontent désormais au feu du Bastion des Braises, comme jadis la légende de l'Âtre-Forge, où tous les métiers du Domaine ont hiverné la chute du monde.",
  "quests:q_skiller_5:name": "Légende de l'Âtre-Forge",
  "quests:q_slagpit_1:description": "Aventurez-vous dans la Fosse de Scories, où l'on fondait jadis le fer divin, et exterminez 20 araignées des fosses tapies dans l'ombre.",
  "quests:q_slagpit_1:name": "Dans la Fosse",
  "quests:q_slagpit_2:description": "Des revenants de fer patrouillent les passages les plus profonds, des forgerons morts dans leur armure, jamais relevés de leur poste. Abattez 10 de ces créations sans mort.",
  "quests:q_slagpit_2:name": "Hantise de fer",
  "quests:q_smith_journeyman:description": "Atteignez le niveau 20 en Forge. La forge du Bastion des Braises récompense la patience : maîtrisez les bases avant de vous attaquer aux métaux plus durs.",
  "quests:q_smith_journeyman:name": "Forgeron compagnon",
  "quests:q_smith_master:description": "Atteignez le niveau 50 en Forge. Seuls les plus dévoués peuvent travailler les métaux les plus rares du Domaine : le fer divin ne pardonne aucune impatience.",
  "quests:q_smith_master:name": "Maître de la forge",
  "quests:q_stag_hunter:description": "Des cerfs sauvages, pareils à des monuments, dominent les Terrains de Chasse de Bois-Sauvage. Abattez 20 de ces fières bêtes.",
  "quests:q_stag_hunter:name": "Roi des bois",
  "quests:q_thorn_wolf_pack:description": "Les loups des ronces du Bois d'Épine-Noire sont plus dangereux que leurs congénères ; le bois les a aiguisés. Tuez-en 20.",
  "quests:q_thorn_wolf_pack:name": "La Meute des loups des ronces",
  "quests:q_wolf_slayer:description": "Chassez 15 loups gris dans les Terrains de Chasse de Bois-Sauvage ; tout y a grandi depuis que plus personne n'y chasse.",
  "quests:q_wolf_slayer:name": "Au cœur de Bois-Sauvage",
  "quests:q_woodcutter_1:description": "Atteignez le niveau 5 en Bûcheronnage. Une hache affûtée et un cœur vaillant suffisent ; le Bastion des Braises n'en demande pas plus.",
  "quests:q_woodcutter_1:name": "Dans les bois",
  "quests:q_woodcutter_2:description": "Atteignez le niveau 15 en Bûcheronnage pour couper les chênes ; le camp a besoin de plus que du petit bois.",
  "quests:q_woodcutter_2:name": "Bûcheron aguerri",
  "quests:q_woodcutter_3:description": "Atteignez le niveau 30 en Bûcheronnage. Les bosquets anciens ne livrent leurs secrets qu'aux dignes ; l'Épine-Noire préfère la révérence à la hâte.",
  "quests:q_woodcutter_3:name": "Maître de la hache",
