  "actions:craft_harvestward_clutch:name": "Forger la chaîne du gardien des récoltes",
  "items:oreveined_hoop:name": "Anneau Veiné de Minerai",
  "items:oreveined_hoop:description": "Serti d'un éclat de saphir sur du minerai brut, sentant encore faiblement le filon dont il fut tiré. Double le rendement d'un coup, de temps à autre.",
  "items:thriftcut_cinch:name": "Anneau de la Coupe Économe",
  "items:thriftcut_cinch:description": "Un diamant serti dans le mithril, poli par des mains qui n'ont jamais gâché la moindre découpe de peau.",
  "items:steadhand_cuff:name": "Anneau de la Main Sûre",
  "items:steadhand_cuff:description": "De l'onyx lié à un fil touché par le néant. Empêche la main de trembler au moment précis où cela compte le plus.",
  "items:harvestward_clutch:name": "Chaîne du Gardien des Récoltes",
  "items:harvestward_clutch:description": "Une chaîne de pierre du néant enveloppée de tissu stellaire, chaude comme une terre retournée même au cœur de l'hiver.",
  "sets:hunters_accord_set:name": "Pacte du Chasseur (2 pièces)",
