  "items:crownless_warbow:name": "Arc de guerre du Sans-Couronne",
  "items:crownless_warbow:description": "Un arc massif de fer divin sombre, les branches serties de pointes de couronne brisées. Drazhan n'a jamais eu besoin de viser quoi que ce soit de petit.",
