  "items:crownless_stave:name": "Bâton du Sans-Couronne",
  "items:crownless_stave:description": "Un bâton de fer divin noir haut comme un homme, surmonté d'une monture de couronne éclatée et vide. Son feu fut emprunté un jour et jamais rendu.",
