  "actions:brew_wardveil_tonic:name": "Préparer Tonique Voile-de-Barrière",
  "actions:brew_windstride_tonic:name": "Préparer Tonique Foulée-de-Vent",
  "items:duskfang_ripper:description": "Un surin courbe forgé dans la serre d'un vautour : léger, vif et cruel au dégainer.",
  "items:ribcage_hewer:description": "Une hache de guerre en écorce d'ent, au tranchant durci dans la sève de Noirépine jusqu'à mordre comme le fer.",
  "items:mossheart_crusher:description": "Un maillet à noyau de golem, de pierre et de racines compactées. Chaque coup s'abat comme un mur qui s'écroule.",
  "items:chorus_impaler:description": "Une pique forgée dans la tombe, la hampe enveloppée d'un linceul. Le silence de la crypte chevauche sa pointe.",
  "items:sentinel_coreblade:description": "Une épée à deux mains forgée dans la plaque-noyau d'un sentinelle tombé. Elle vibre faiblement de sa charge de barrière résiduelle.",
  "items:colossus_marrowaxe:description": "Un énorme fer de hache taillé dans un os de moelle pétrifié. Il fend droit vers la plus grosse cible de la pièce.",
  "items:wisp_kindled_bough:description": "Une branche de bois des marais dont l'extrémité noueuse fume encore du feu follet qu'elle a piégé.",
  "items:chitinshell_sparker:description": "Une baguette au cœur de chitine de scarabée, qui crépite d'électricité statique à chaque coup.",
  "items:barrowsong_crook:description": "Un sceptre funéraire arraché à un chantre de tumulus, encore froid au toucher.",
  "items:briarbound_conduit:description": "Un orbe catalyseur lié de ronces vivantes, qui vibre du savoir-faire résiduel de la sorcière.",
  "items:choirbound_relic:description": "Un bâton récupéré dans le sanctuaire du chœur creux. Il porte leur bourdonnement dans chaque coup.",
  "items:voidherald_flightbow:description": "Un arc long cordé de nerf marqué par le néant, tiré du reliquaire du héraut lui-même.",
  "items:soulflayer_snapbow:description": "Un arc court et vicieux taillé dans la corne d'âmes écorchées. Sa corde se tend presque sans bruit.",
  "items:voidhusk_deadeye:description": "Un lourd arc long plaqué de coque du néant, conçu pour un seul tir mortel à la fois.",
